// Roadmap slide — sits right after the intro. Two acts, one per "page":
//   Page 1 — a year of university cryptography, distilled into a few minutes.
//   Page 2 — how a YubiKey actually does this (topics in slide order).
// Step 0 shows page 1; step 1 scrolls down one full viewport to page 2, so the
// title / subtitle / act 1 slide up out of view and each act gets the whole canvas.
// A future "hacker's perspective" beat could attach as a third page here later.

private data class Stop(val icon: ImageVector, val title: String, val sub: String)

private val cryptoStops: List<Stop> = listOf(
    Stop(Icons.Default.Lock, "Data & symmetric encryption", "it's all just bits"),
    Stop(Icons.Default.VpnKey, "Asymmetric encryption", "two keys, one public"),
    Stop(Icons.Default.Draw, "Signing\n", "zero-knowledge proofs")
)

private val yubikeyStops: List<Stop> = listOf(
    Stop(Icons.Default.Casino, "Challenge–response", "proves it's you"),
    Stop(Icons.Default.Keyboard, "HID", "a keyboard"),
    Stop(Icons.Default.Shield, "Passkeys", "Phishing-resistant"),
    Stop(Icons.Default.Usb, "Our key", "the device")
)

/** One roadmap "stop": an accent icon badge, a title, and a short subtitle. */
@Composable
private fun StopCard(stop: Stop, accent: Color) {
    Column(
        modifier = Modifier
            .width(178.dp)
            .clip(RoundedCornerShape(12.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .padding(12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Box(
            modifier = Modifier
                .size(40.dp)
                .clip(CircleShape)
                .background(accent.copy(alpha = 0.18f)),
            contentAlignment = Alignment.Center
        ) {
            Icon(stop.icon, contentDescription = null, tint = accent, modifier = Modifier.size(22.dp))
        }
        Text(
            stop.title,
            style = MaterialTheme.typography.titleSmall,
            fontWeight = FontWeight.Bold,
            color = MaterialTheme.colorScheme.onSurface,
            textAlign = TextAlign.Center,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
        )
        Text(
            stop.sub,
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            textAlign = TextAlign.Center,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
        )
    }
}

/** The chevron linking two stops. */
@Composable
private fun Chevron() {
    Icon(
        imageVector = Icons.Default.ChevronRight,
        contentDescription = null,
        tint = MaterialTheme.colorScheme.onSurfaceVariant,
        modifier = Modifier.size(22.dp)
    )
}

/** An act header pill: a numbered badge + the act's title, in the act's accent. */
@Composable
private fun ActHeader(part: Int, title: String, accent: Color, container: Color, onContainer: Color) {
    Row(
        modifier = Modifier
            .clip(RoundedCornerShape(20.dp))
            .background(container)
            .padding(horizontal = 14.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        Box(
            modifier = Modifier
                .size(24.dp)
                .clip(CircleShape)
                .background(accent),
            contentAlignment = Alignment.Center
        ) {
            Text("$part", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = Color.Black)
        }
        Text(title, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Bold, color = onContainer)
    }
}

/** A full lane: the act header above a centered row of stops linked by chevrons. */
@Composable
private fun Lane(stops: List<Stop>, part: Int, title: String) {
    val accent = if (part == 1) MaterialTheme.colorScheme.secondary else MaterialTheme.colorScheme.primary
    val container = if (part == 1) MaterialTheme.colorScheme.secondaryContainer else MaterialTheme.colorScheme.primaryContainer
    val onContainer = if (part == 1) MaterialTheme.colorScheme.onSecondaryContainer else MaterialTheme.colorScheme.onPrimaryContainer

    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        ActHeader(part, title, accent, container, onContainer)
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp, Alignment.CenterHorizontally),
            verticalAlignment = Alignment.CenterVertically
        ) {
            stops.forEachIndexed { i, stop ->
                if (i > 0) Chevron()
                StopCard(stop, accent)
            }
        }
    }
}

val roadmap by Slide(stepCount = 2, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    // Two full-viewport pages stacked in one scrollable column. Step 1 scrolls
    // down exactly one viewport, so page 2 takes the canvas and the title /
    // page 1 slide up out of view.
    val scrollState = rememberScrollState()
    val density = LocalDensity.current
    var viewportH by remember { mutableStateOf(0) }

    LaunchedEffect(step, viewportH) {
        if (viewportH > 0) scrollState.animateScrollTo(
            if (step >= 1) viewportH else 0,
            animationSpec = tween(durationMillis = 700)
        )
    }

    val pageHeight = with(density) { viewportH.toDp() }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .onSizeChanged { viewportH = it.height }
            .verticalScroll(scrollState),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        // Page 1 — title + crypto act.
        Column(
            modifier = Modifier.fillMaxWidth().height(pageHeight).padding(24.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp, Alignment.CenterVertically),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.Map,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.size(30.dp)
                )
                Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text("Roadmap", style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
                    Text("what we'll cover", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                }
            }
            Lane(cryptoStops, part = 1, title = "A year of cryptography, in minutes")
        }

        // Page 2 — YubiKey act.
        Column(
            modifier = Modifier.fillMaxWidth().height(pageHeight).padding(24.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp, Alignment.CenterVertically),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Lane(yubikeyStops, part = 2, title = "How a YubiKey does this")
        }
    }
}
