// Beat [7] — Passkeys: the browser / password-manager validates that a challenge
// really comes from the origin it claims (origin / RP-ID binding). A phishing
// page can mimic bank.com visually, but the browser reports the *real* origin, so
// a fake site can never obtain a signature valid for the real one. → unphishable.

private val green = Color(76f / 255f, 175f / 255f, 80f / 255f)
private val red = Color(229f / 255f, 57f / 255f, 53f / 255f)

@Composable
private fun Panel(
    modifier: Modifier = Modifier,
    title: String,
    accent: Color? = null,
    content: @Composable () -> Unit
) {
    Column(
        modifier = modifier
            .clip(RoundedCornerShape(10.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .then(if (accent != null) Modifier.border(2.dp, accent, RoundedCornerShape(10.dp)) else Modifier)
            .padding(10.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        Text(title, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
        content()
    }
}

@Composable
private fun Chip(text: String, color: Color) {
    Text(text, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = color)
}

/** The origin line, split ("origin:" / domain) over two lines in a fixed-width box, so step 0 (bank.com) and step 1 (evil.com) don't change width and shift the surrounding layout. */
@Composable
private fun OriginChip(origin: String, accent: Color) {
    Column(
        modifier = Modifier.width(80.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text("origin:", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = accent)
        Text(origin, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = accent)
    }
}

val passkey by Slide(stepCount = 2, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    val phish = step >= 1
    val siteName = if (phish) "evil.com" else "bank.com"
    val siteSub = if (phish) "impersonating bank.com" else "the real bank\n "
    val origin = if (phish) "evil.com" else "bank.com"
    val ok = !phish
    val accent = if (ok) green else red
    val resultIcon = if (ok) Icons.Default.Check else Icons.Default.Close
    val resultText = if (ok) "signs" else "refuses"
    val check = if (ok) "origin matches" else "origin mismatch"


    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            "Passkeys add one thing: the browser validates the source",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )

        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            // Site
            Panel(modifier = Modifier.width(118.dp), title = "site") {
                Text(siteName, style = MaterialTheme.typography.bodyLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface)
                Text(siteSub, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
            }
            // challenge + origin (the part Passkeys add a check on)
            Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text("challenge", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowRight,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.size(22.dp)
                )
                OriginChip(origin, accent)
            }
            // Authenticator (constant across steps)
            Panel(modifier = Modifier.width(150.dp), title = "browser / password manager") {
                Icon(
                    imageVector = Icons.Default.VpnKey,
                    contentDescription = "Passkey",
                    modifier = Modifier.size(30.dp),
                    tint = MaterialTheme.colorScheme.primary
                )
                Text("holds your passkey", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                Chip("registered: bank.com", MaterialTheme.colorScheme.onSurface)
            }
            Icon(
                imageVector = Icons.AutoMirrored.Filled.ArrowRight,
                contentDescription = null,
                tint = accent,
                modifier = Modifier.size(22.dp)
            )
            // Result
            Panel(modifier = Modifier.width(108.dp), title = "outcome", accent = accent) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Icon(imageVector = resultIcon, contentDescription = null, tint = accent, modifier = Modifier.size(20.dp))
                    Text(resultText, style = MaterialTheme.typography.bodyLarge, fontWeight = FontWeight.Bold, color = accent)
                }
                Text(check, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
            }
        }

        val arrowColor = MaterialTheme.colorScheme.onSurfaceVariant
        Text(
            text = buildAnnotatedString {
                if (ok) {
                    append("Origin matches the registered one ")
                    appendInlineContent("arrow")
                    append(" the passkey signs. Your real login works.")
                } else {
                    append("The browser reports the REAL origin (evil.com), not the page's claim ")
                    appendInlineContent("arrow")
                    append(" mismatch ")
                    appendInlineContent("arrow")
                    append(" refused. Not phishable.")
                }
            },
            style = MaterialTheme.typography.bodyMedium,
            color = arrowColor,
            inlineContent = mapOf(
                "arrow" to InlineTextContent(
                    Placeholder(
                        width = MaterialTheme.typography.bodyMedium.fontSize,
                        height = MaterialTheme.typography.bodyMedium.fontSize,
                        placeholderVerticalAlign = PlaceholderVerticalAlign.TextCenter
                    )
                ) { _ ->
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowRight,
                        contentDescription = null,
                        tint = arrowColor,
                        modifier = Modifier.fillMaxSize()
                    )
                }
            )
        )
    }
}
