// A finite chain is a close-up of a cycle. Bend an arc of constant local spacing,
// pull the camera back, then close the seam. No rearrangement-by-crossfade and no
// interactive elements: both diagrams share one procedural drawing vocabulary.
private const val N = 33
private val santaCycle = listOf(0, 3, 5, 1, 7, 10, 4, 9, 6, 8, 2)
private val nodeBits = List(N) { i ->
    val value = if (i % 3 == 0) santaCycle[i / 3] else (i * 7 + 3) % 16
    value.toString(2).padStart(4, '0')
}
private val columnBits = List(N) { i ->
    when (i) {
        0 -> "0110100111010110"
        1 -> "1001101000101101"
        else -> ((i * 4051 + 29017) and 65535).toString(2).padStart(16, '0')
    }.take(14)
}

private fun phase(t: Float, start: Float, end: Float): Float {
    val u = ((t - start) / (end - start)).coerceIn(0f, 1f)
    return u * u * (3f - 2f * u)
}

private fun mix(a: Float, b: Float, t: Float) = a + (b - a) * t
private fun mix(a: Offset, b: Offset, t: Float) = a + (b - a) * t

val sameShape by Slide(stepCount = 2, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    // One deliberate, staged shot: discover more chain, bend it, close the loop,
    // then let the audience sit with the two identical silhouettes.
    val progress by animateFloatAsState(
        targetValue = if (step >= 1) 1f else 0f,
        animationSpec = tween(durationMillis = 4800, easing = LinearEasing),
        label = "chain-to-cycle"
    )
    val measurer = rememberTextMeasurer()
    val colors = MaterialTheme.colorScheme

    Column(
        modifier = Modifier.fillMaxSize().padding(horizontal = 20.dp, vertical = 12.dp),
        verticalArrangement = Arrangement.spacedBy(6.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Canvas(modifier = Modifier.fillMaxWidth().weight(1f)) {
            val panelWidth = size.width * 0.46f
            val leftCenter = Offset(size.width * 0.25f, size.height * 0.52f)
            val rightCenter = Offset(size.width * 0.75f, size.height * 0.52f)
            val radius = min(panelWidth * 0.37f, size.height * 0.32f)
            val grow = phase(progress, 0f, 0.66f)
            val bend = phase(progress, 0.12f, 0.88f)
            val settle = phase(progress, 0.7f, 0.95f)
            val detail = phase(progress, 0.35f, 0.9f)
            val bitTextAlpha = 1f - phase(progress, 0.43f, 0.52f)
            val circleNodeR = radius * 0.072f
            val startWidth = radius * 0.26f
            val startHeight = radius * 1.65f
            val cardWidth = mix(startWidth, circleNodeR * 2f, detail)
            val cardHeight = mix(startHeight, circleNodeR * 2f, detail)
            val stretch = mix(3.2f, 1f, grow)

            // A genuine arc, not a lerp of unrelated layouts: curvature starts at
            // zero (straight chain) and increases until the arc closes on itself.
            fun chainPosition(j: Int): Offset {
                val angle = ((j - 0.5f) * 2.0 * PI / N).toFloat()
                val curvature = bend
                val anchor = mix(leftCenter, leftCenter - Offset(0f, radius), bend)
                if (curvature < 0.001f) return anchor + Offset(radius * angle * stretch, 0f)
                val theta = angle * curvature
                return anchor + Offset(
                    radius / curvature * stretch * sin(theta),
                    radius / curvature * stretch * (1f - cos(theta))
                )
            }
            fun chainAlpha(j: Int): Float {
                if (j == 0 || j == 1) return 1f
                val distance = min(kotlin.math.abs(j), kotlin.math.abs(j - 1))
                val threshold = (distance - 1) / 18f
                return phase(progress, threshold, threshold + 0.13f)
            }
            val first = -15
            val last = 17

            // Clip the camera, not the world. The chain genuinely extends beyond
            // the panel before the pullback; its neighbours are not layout-capped.
            withTransform({ clipRect(0f, 0f, size.width * 0.49f, size.height) }) {
                // Continuation arrows are visible in the original two-column
                // close-up, before the neighbouring columns enter the shot.
                for (j in listOf(-1, 1)) {
                    moneyArrow(chainPosition(j), chainPosition(j + 1), cardWidth * 0.58f,
                        colors.tertiary, (1f - grow) * 0.55f, radius * 0.033f)
                }
                for (j in first until last) {
                    val a = min(chainAlpha(j), chainAlpha(j + 1))
                    val from = chainPosition(j)
                    val to = chainPosition(j + 1)
                    val inset = mix(cardWidth * 0.58f, circleNodeR, detail)
                    val forward = lerp(colors.tertiary, colors.primary, settle)
                    moneyArrow(from, to, inset, forward, a, radius * 0.033f)
                    // Keep Alice/Bob's purple inverse visible in the close-up;
                    // remove the duplicated reverse edges as the cycle resolves.
                    if (detail < 1f) {
                        val offset = Offset(0f, cardHeight * 0.22f)
                        moneyArrow(to + offset, from + offset, inset, colors.primary,
                            a * (1f - detail), radius * 0.033f)
                    }
                }
                moneyArrow(chainPosition(last), chainPosition(first), circleNodeR,
                    colors.primary, settle, radius * 0.033f)

                for (j in first..last) {
                    val i = (j % N + N) % N
                    val position = chainPosition(j)
                    val a = chainAlpha(j)
                    if (a <= 0f) continue
                    val tilt = ((j - 0.5f) * 360f / N) * bend * (1f - settle)
                    withTransform({
                        translate(position.x, position.y)
                        rotate(tilt, Offset.Zero)
                    }) {
                        moneyCard(Offset.Zero, cardWidth, cardHeight,
                            mix(radius * 0.05f, circleNodeR, detail), colors.surfaceVariant,
                            colors.onSurfaceVariant, a)
                        if (detail < 1f) {
                            val text = columnBits[i].toCharArray().joinToString("\n")
                            moneyText(text, Offset.Zero, startHeight * 0.049f,
                                colors.onSurface, a * (1f - detail) * bitTextAlpha, measurer)
                        }
                        moneyText(nodeBits[i], Offset.Zero, circleNodeR * 0.62f,
                            colors.onSurface, a * detail * bitTextAlpha, measurer)
                    }
                }
            }

            // Insert one node at twelve o'clock per beat. Existing nodes retain
            // their identities and slide clockwise into the new equal spacing;
            // no crossfade between old and new rings. The short hold at each
            // beat's end makes the individual insertions visibly staggered.
            val insertion = ((progress - 0.12f) / 0.76f).coerceIn(0f, 1f) * (N - 11)
            val completed = floor(insertion).toInt().coerceAtMost(N - 11)
            val inserting = completed < N - 11
            val move = if (inserting) phase(insertion - completed, 0f, 0.82f) else 0f
            val birth = if (inserting) phase(insertion - completed, 0.1f, 0.72f) else 0f
            val order = (0 until 11).toMutableList()
            repeat(completed) { order.add(0, 11 + it) }
            val count = order.size
            // Only after the last insertion, align the ring with the left's
            // final half-step orientation. Births themselves stay at 12 o'clock.
            val orientation = -PI.toFloat() / N * phase(progress, 0.88f, 0.95f)
            fun ringPoint(angle: Float): Offset = rightCenter +
                Offset(radius * sin(angle + orientation), -radius * cos(angle + orientation))
            val positions = List(count) { slot ->
                val oldAngle = (2.0 * PI * slot / count).toFloat()
                val newAngle = (2.0 * PI * (slot + 1) / (count + 1)).toFloat()
                ringPoint(mix(oldAngle, newAngle, move))
            }
            val incoming = ringPoint(0f)
            val nodeRadius = circleNodeR * mix(1.7f, 1f, detail)
            for (slot in 0 until count - 1) {
                moneyArrow(positions[slot], positions[slot + 1], nodeRadius,
                    colors.primary, 1f, radius * 0.033f)
            }
            moneyArrow(positions.last(), positions.first(), nodeRadius,
                colors.primary, if (inserting) 1f - birth else 1f, radius * 0.033f)
            if (inserting) {
                moneyArrow(positions.last(), incoming, nodeRadius,
                    colors.primary, birth, radius * 0.033f)
                moneyArrow(incoming, positions.first(), nodeRadius,
                    colors.primary, birth, radius * 0.033f)
            }
            fun ringNode(id: Int, position: Offset, alpha: Float) {
                moneyCard(position, nodeRadius * 2f, nodeRadius * 2f, nodeRadius,
                    colors.surfaceVariant, colors.onSurfaceVariant, alpha)
                val bits = if (id < 11) santaCycle[id].toString(2).padStart(4, '0') else nodeBits[id]
                moneyText(bits, position, nodeRadius * 0.62f, colors.onSurface,
                    alpha * bitTextAlpha, measurer)
            }
            order.forEachIndexed { slot, id -> ringNode(id, positions[slot], 1f) }
            if (inserting) ringNode(11 + completed, incoming, birth)

            moneyText("PUBLIC-KEY ENCRYPTION", Offset(leftCenter.x, size.height * 0.065f),
                size.height * 0.035f, colors.onSurfaceVariant, 1f, measurer, mono = false)
            moneyText("SECRET SANTA", Offset(rightCenter.x, size.height * 0.065f),
                size.height * 0.035f, colors.onSurfaceVariant, 1f, measurer, mono = false)

            // A quiet equals sign is the final beat, not a competing headline.
            moneyText("=", Offset(size.width * 0.5f, leftCenter.y), radius * 0.35f,
                colors.primary, settle, measurer, mono = false)
            val verdictAlpha = phase(progress, 0.83f, 1f)
            moneyText("The same shape.", Offset(size.width * 0.5f, size.height * 0.94f),
                size.height * 0.052f, colors.onSurface, verdictAlpha, measurer, mono = false)
        }
        Text(
            "Anyone can go forward: encrypt · ask who someone gives to.",
            style = MaterialTheme.typography.bodyMedium,
            color = colors.tertiary,
            textAlign = TextAlign.Center
        )
        Text(
            "Going back is the hard part. Doing it proves you know the secret.",
            style = MaterialTheme.typography.bodyMedium,
            color = colors.onSurface,
            textAlign = TextAlign.Center
        )
    }
}

private fun DrawScope.moneyArrow(
    from: Offset, to: Offset, inset: Float, color: Color, alpha: Float, headSize: Float
) {
    if (alpha <= 0f) return
    val delta = to - from
    val length = delta.getDistance()
    if (length <= inset * 2f + headSize) return
    val direction = delta / length
    val start = from + direction * inset
    val tip = to - direction * inset
    val perpendicular = Offset(-direction.y, direction.x)
    val base = tip - direction * headSize
    val ink = color.copy(alpha = alpha.coerceIn(0f, 1f))
    drawLine(ink, start, base, strokeWidth = (headSize * 0.28f).coerceAtLeast(1f))
    drawPath(Path().apply {
        moveTo(tip.x, tip.y)
        lineTo(base.x + perpendicular.x * headSize * 0.55f, base.y + perpendicular.y * headSize * 0.55f)
        lineTo(base.x - perpendicular.x * headSize * 0.55f, base.y - perpendicular.y * headSize * 0.55f)
        close()
    }, ink)
}

private fun DrawScope.moneyCard(
    center: Offset, width: Float, height: Float, corner: Float,
    fill: Color, border: Color, alpha: Float
) {
    val topLeft = center - Offset(width / 2f, height / 2f)
    val dimensions = Size(width, height)
    val rounding = CornerRadius(corner, corner)
    drawRoundRect(fill.copy(alpha = alpha), topLeft, dimensions, rounding)
    drawRoundRect(border.copy(alpha = alpha * 0.6f), topLeft, dimensions, rounding,
        style = Stroke(width = (width * 0.025f).coerceAtLeast(1f)))
}

// Font sizes are derived from the camera geometry, then converted from px to sp.
// This keeps text inside its nodes regardless of the slide's logical dp size.
private fun DrawScope.moneyText(
    text: String, center: Offset, fontPixels: Float, color: Color, alpha: Float,
    measurer: TextMeasurer, mono: Boolean = true
) {
    if (alpha <= 0f || fontPixels <= 0f) return
    val layout = measurer.measure(text, TextStyle(
        color = color.copy(alpha = alpha.coerceIn(0f, 1f)),
        fontSize = fontPixels.toSp(),
        lineHeight = (fontPixels * 1.18f).toSp(),
        fontFamily = if (mono) FontFamily.Monospace else FontFamily.Default,
        fontWeight = FontWeight.Bold,
        textAlign = TextAlign.Center
    ))
    drawText(layout, topLeft = center - Offset(layout.size.width / 2f, layout.size.height / 2f))
}
