}

/** Scenes 1–2: a public key encrypts bits; the private key is its inverse — then,
 *  at step 2, the view zooms out (animated) to reveal the same operation repeated
 *  across more bit columns. The flanking columns exist from the start, laid out
 *  full-size and clipped off-screen by the canvas; the zoom-out genuinely reveals
 *  them. Text (title + labels) fades out as the zoom happens, leaving just bits
 *  + arrows. Centre pair = the original plaintext/ciphertext; flanking columns
 *  fade to 80% / 60% to read as "…and so on". */
@Composable
private fun EncryptDecryptScene(step: Int) {
    var viewportW by remember { mutableStateOf(0) }
    var lineW by remember { mutableStateOf(0) }
    // Zoom target at step 2: scale down just enough that the whole (wide) row fits
    // the canvas, so the off-screen flanking columns slide into view. Measured so it
    // is correct regardless of window size / density (~50% on a typical display).
    val finalZoom = if (lineW > 0 && viewportW > 0) (viewportW.toFloat() / lineW).coerceAtMost(1f) else 1f
    val zoom by animateFloatAsState(
        targetValue = if (step >= 2) finalZoom else 1f,
        animationSpec = spring(stiffness = Spring.StiffnessMediumLow),
        label = "zoom"
    )
    val textAlpha by animateFloatAsState(
        targetValue = if (step >= 2) 0f else 1f,
        animationSpec = spring(stiffness = Spring.StiffnessMediumLow),
        label = "textAlpha"
    )

    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            "Public key encrypts — private key is the inverse",
            style = MaterialTheme.typography.headlineSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.alpha(textAlpha)
        )
        // clipToBounds hides the flanking columns that overflow the canvas at full
        // zoom; the inner wrapContentWidth(unbounded = true) lets the row measure its
        // true (wide) content width for the zoom-target calculation.
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f)
                .clipToBounds()
                .onSizeChanged { viewportW = it.width },
            contentAlignment = Alignment.Center
        ) {
            Box(
                modifier = Modifier
                    .wrapContentWidth(unbounded = true)
                    .onSizeChanged { lineW = it.width }
            ) {
                Row(
                    modifier = Modifier
                        .graphicsLayer(
                            scaleX = zoom,
                            scaleY = zoom,
                            transformOrigin = TransformOrigin(0.5f, 0.5f)
                        ),
                    horizontalArrangement = Arrangement.spacedBy(110.dp, Alignment.CenterHorizontally),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    BitColumn(sideBitsD, alpha = 0.6f)
                    ArrowsGap()
                    BitColumn(sideBitsB, alpha = 0.8f)
                    ArrowsGap()
                    BitsBlock(label = "plaintext", bits = plainBits, labelAlpha = textAlpha)
                    LabeledArrowsGap(labelAlpha = textAlpha)
                    BitsBlock(label = "ciphertext", bits = cipherBits, emphasized = true, labelAlpha = textAlpha)
                    ArrowsGap()
                    BitColumn(sideBitsA, alpha = 0.8f)
                    ArrowsGap()
                    BitColumn(sideBitsC, alpha = 0.6f)
                }
            }
        }
    }
}

/** A vertical column of bits (no label), with optional emphasis + opacity. */
@Composable
private fun BitColumn(bits: String, emphasized: Boolean = false, alpha: Float = 1f) {
    Box(
        modifier = Modifier
            .alpha(alpha)
            .clip(RoundedCornerShape(8.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .padding(horizontal = 12.dp, vertical = 10.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = bits.toCharArray().joinToString("\n"),
            fontSize = 14.sp,
            lineHeight = 12.sp,
            fontFamily = FontFamily.Monospace,
            fontWeight = if (emphasized) FontWeight.Bold else FontWeight.Normal,
            color = MaterialTheme.colorScheme.onSurface
        )
    }
}

/** The two label-free arrows between adjacent bit columns: public key → (tertiary)
 *  and private key ← (primary). */
@Composable
private fun ArrowsGap() {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(48.dp)
    ) {
        ArrowGraphic(leftToRight = true, color = MaterialTheme.colorScheme.tertiary)
        ArrowGraphic(leftToRight = false, color = MaterialTheme.colorScheme.primary)
    }
}

/** The centre gap — the labelled public/private-key arrows (it visually matches the
 *  label-free ArrowsGap once the labels fade out at step 2). */
@Composable
private fun LabeledArrowsGap(labelAlpha: Float) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(48.dp)
    ) {
        Arrow(label = "public key", leftToRight = true, color = MaterialTheme.colorScheme.tertiary, sub = "encrypt", labelAlpha = labelAlpha)
        Arrow(label = "private key", leftToRight = false, color = MaterialTheme.colorScheme.primary, sub = "the inverse", labelAlpha = labelAlpha)
    }
}

/** A labelled, monospaced block of "random" bits — a visual placeholder (no real arithmetic). The label fades with labelAlpha. */
@Composable
private fun BitsBlock(label: String, bits: String, emphasized: Boolean = false, labelAlpha: Float = 1f) {
    Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(4.dp)) {
        Text(
            label,
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.alpha(labelAlpha)
        )
        Box(
            modifier = Modifier
                .clip(RoundedCornerShape(8.dp))
                .background(MaterialTheme.colorScheme.surfaceVariant)
                .padding(horizontal = 12.dp, vertical = 10.dp),
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = bits.toCharArray().joinToString("\n"),
                fontSize = 14.sp,
                lineHeight = 12.sp,
                fontFamily = FontFamily.Monospace,
                fontWeight = if (emphasized) FontWeight.Bold else FontWeight.Normal,
                color = MaterialTheme.colorScheme.onSurface
            )
        }
    }
}

/** A labelled key card: an accent dot, a label, and a short subtitle. */
@Composable
private fun KeyCard(label: String, sub: String, isPrivate: Boolean) {
    val accent = if (isPrivate) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.tertiary
    Row(
        modifier = Modifier
            .width(170.dp)
            .clip(RoundedCornerShape(8.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant)
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Box(Modifier.size(10.dp).clip(CircleShape).background(accent)) {}
        Column {
            Text(
                text = label,
                style = MaterialTheme.typography.labelLarge,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )
            Text(
                text = sub,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}

