/** The chevron + shaft of an arrow, with no label. */
@Composable
private fun ArrowGraphic(leftToRight: Boolean, color: Color) {
    Row(verticalAlignment = Alignment.CenterVertically) {
        if (!leftToRight) {
            Icon(imageVector = Icons.Default.ChevronLeft, contentDescription = null, tint = color, modifier = Modifier.size(28.dp))
        }
        Box(
            modifier = Modifier
                .height(3.dp)
                .width(96.dp)
                .background(color)
        )
        if (leftToRight) {
            Icon(imageVector = Icons.Default.ChevronRight, contentDescription = null, tint = color, modifier = Modifier.size(28.dp))
        }
    }
}

/** A labelled horizontal arrow; leftToRight picks the head side. color tints the shaft/head/label; sub is an optional caption below the label. labelAlpha fades the text (used for the step-2 zoom-out). */
@Composable
private fun Arrow(
    label: String,
    leftToRight: Boolean,
    color: Color = MaterialTheme.colorScheme.primary,
    sub: String? = null,
    labelAlpha: Float = 1f
) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        ArrowGraphic(leftToRight = leftToRight, color = color)
        Text(
            label,
            style = MaterialTheme.typography.labelMedium,
            color = color,
            modifier = Modifier.alpha(labelAlpha)
        )
        if (sub != null) {
            Text(
                sub,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.alpha(labelAlpha)
            )
        }
    }
}
