package slides

import androidx.compose.animation.core.animateFloatAsState
import androidx.compose.animation.core.tween
import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.size
import androidx.compose.foundation.layout.width
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.alpha
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.RectangleShape
import androidx.compose.ui.unit.dp
import net.kodein.cup.SLIDE_SIZE_16_9
import net.kodein.cup.Slide
import net.kodein.cup.SlideSpecs
import net.kodein.cup.ui.styled
import org.jetbrains.compose.resources.painterResource
import yubikeys_pres.generated.resources.Res
import yubikeys_pres.generated.resources.monkey_hamlet

// Beat [2.5] — the bridge between asymmetric crypto and zero-knowledge:
// "impossible" is just a timescale; proof is "true, or impossibly lucky."
// The image stays in the layout at all times; its width animates 0 -> full so the
// text column (weight 1f) reflows every frame and the text genuinely slides right.
// The image is revealed with a left-to-right wipe + fade driven by the same value.
private val imageWidth = 224.dp
private val imageHeight = 220.dp
private val imageGap = 24.dp

val impossible by Slide(stepCount = 2, specs = SlideSpecs(size = SLIDE_SIZE_16_9)) { step ->
    // 0f = hidden, 1f = fully revealed. Drives the wipe, the fade, and the layout push.
    val reveal = animateFloatAsState(
        targetValue = if (step >= 1) 1f else 0f,
        animationSpec = tween(durationMillis = 600)
    ).value

    Row(
        modifier = Modifier.fillMaxSize().padding(16.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        // Left — the monkey-hamlet image. Always laid out; its width grows 0 -> full,
        // clipping the full-size image for a left-to-right wipe while fading it in.
        Box(
            modifier = Modifier
                .width(imageWidth * reveal)
                .clip(RectangleShape),
            contentAlignment = Alignment.CenterStart
        ) {
            Image(
                painter = painterResource(Res.drawable.monkey_hamlet),
                contentDescription = null,
                modifier = Modifier
                    .size(width = imageWidth, height = imageHeight)
                    .alpha(reveal)
            )
        }

        // Gap grows with the image so step 0 keeps the original centered text.
        Spacer(modifier = Modifier.width(imageGap * reveal))

        // Right — the text, reflowing (sliding right) as the image takes space.
        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(20.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                styled {
                    "In crypto, ${+b}impossible${-b} just means:\ntakes longer than the ${+b}heat death of the universe${-b}."
                },
                style = MaterialTheme.typography.headlineSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            Text(
                styled {
                    "You don't ${+b}prove${-b} a claim —\nyou prove it's true, or you got ${+b}impossibly lucky${-b}."
                },
                style = MaterialTheme.typography.headlineSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}
